update cellar.products set image_url = coalesce(image_url, 'https://yellowstonebourbon.com/wp-content/themes/yellowstonebourbon/imgs/bottles/american-single-malt-whiskey.png'), producer = coalesce(producer, 'Yellowstone'), producer_id = coalesce(producer_id, '9dd3470a-ed3f-419b-b083-519410d3a6a4'::uuid), source = 'maker', source_url = 'https://yellowstonebourbon.com/american-single-malt/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '7544a316-fa94-492f-bfc5-042909f20834' and facts_verified_at is null;
update cellar.products set proof = 105.0, age_years = 10.0, age_label = '10 yr', nas = false, image_url = coalesce(image_url, 'https://yellowstonebourbon.com/wp-content/themes/yellowstonebourbon/imgs/bottles/limited-edition-2025.avif'), producer = coalesce(producer, 'Yellowstone'), producer_id = coalesce(producer_id, '9dd3470a-ed3f-419b-b083-519410d3a6a4'::uuid), source = 'maker', source_url = 'https://yellowstonebourbon.com/limited-edition/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '7bfb72c4-bd96-4ed1-ab00-4ed399764c1d' and facts_verified_at is null;
