update cellar.products set proof = 100.0, age_years = 7.0, age_label = '7 yr', nas = false, bottled_in_bond = true, producer = coalesce(producer, 'Yellowstone'), producer_id = coalesce(producer_id, '9dd3470a-ed3f-419b-b083-519410d3a6a4'::uuid), source = 'maker', source_url = 'https://yellowstonebourbon.com/single-barrel/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = 'a46b41d1-f829-439e-8708-a9909753bd77' and facts_verified_at is null;
update cellar.products set image_url = coalesce(image_url, 'https://yellowstonebourbon.com/wp-content/themes/yellowstonebourbon/imgs/bottles/yellowstone_smallBatch.png'), producer = coalesce(producer, 'Yellowstone'), producer_id = coalesce(producer_id, '9dd3470a-ed3f-419b-b083-519410d3a6a4'::uuid), source = 'maker', source_url = 'https://yellowstonebourbon.com/small-batch-107/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = 'd318655d-a1ab-4db7-881a-e7a1b3ab682b' and facts_verified_at is null;
