update cellar.products set source = 'maker', source_url = 'https://yellowstonebourbon.com/select-bourbon/', discontinued = false, catalog_included = catalog_included or is_core_range, producer = coalesce(producer, 'Yellowstone'), producer_id = coalesce(producer_id, '9dd3470a-ed3f-419b-b083-519410d3a6a4'::uuid), image_url = coalesce(image_url, 'https://yellowstonebourbon.com/wp-content/themes/yellowstonebourbon/imgs/bottles/select-bourbon.png') where id = '2a78f5a1-6906-4340-a12b-de1a00a1a3e4' and facts_verified_at is null;
insert into cellar.product_images (product_id, image_url, is_hero) select p.id, p.image_url, true from cellar.products p where p.type = 'bourbon' and p.source = 'maker' and p.image_url like 'https://yellowstonebourbon.com/%' and not exists (select 1 from cellar.product_images i where i.product_id = p.id);
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', '{}'::jsonb, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), r.img, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Yellowstone Special Finishes Rum Cask","rar":"lottery","f":"Yellowstone","x":"Special Finishes Rum Cask","p":100.0,"ay":4.0,"al":"4 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://yellowstonebourbon.com/wp-content/themes/yellowstonebourbon/imgs/bottles/rum-cask.png","u":"https://yellowstonebourbon.com/rum-cask/","pr":"Yellowstone","mk":"9dd3470a-ed3f-419b-b083-519410d3a6a4"},{"n":"Yellowstone Special Finishes Toasted","rar":"lottery","f":"Yellowstone","x":"Special Finishes Toasted","p":100.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":"Cocoa And Tobacco With A Crisp Oak","msrp":null,"core":false,"al2":[],"img":"https://yellowstonebourbon.com/wp-content/themes/yellowstonebourbon/imgs/bottles/Yellowstone_Toasted_SFC.png","u":"https://yellowstonebourbon.com/special-finishes-collection-toasted/","pr":"Yellowstone","mk":"9dd3470a-ed3f-419b-b083-519410d3a6a4"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
