select cellar.merge_product('da025fd5-2f68-46b6-aa12-f00dda369a67', 'a46b41d1-f829-439e-8708-a9909753bd77', null);
select cellar.merge_product('d8136ef0-5d99-4625-a164-ccfa34cfa586', '7bfb72c4-bd96-4ed1-ab00-4ed399764c1d', null);

